import { useState } from 'react'
import { siteConfig } from '../config/site'

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false)

  return (
    <header style={{
      position: 'sticky',
      top: 0,
      zIndex: 50,
      background: 'rgba(255,255,255,0.85)',
      backdropFilter: 'saturate(180%) blur(20px)',
      WebkitBackdropFilter: 'saturate(180%) blur(20px)',
      borderBottom: '1px solid var(--border)',
    }}>
      <div style={{
        maxWidth: 1024,
        margin: '0 auto',
        padding: '0 22px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        height: 48,
      }}>
        <a href="index.html" style={{ textDecoration: 'none', color: 'var(--text-primary)' }}>
          <svg width="18" height="18" viewBox="0 0 18 18" fill="currentColor">
            <path d="M14.5 3.5C14.5 5.16 13.16 6.5 11.5 6.5C9.84 6.5 8.5 5.16 8.5 3.5C8.5 1.84 9.84 0.5 11.5 0.5C13.16 0.5 14.5 1.84 14.5 3.5ZM6.5 3.5C6.5 5.16 5.16 6.5 3.5 6.5C1.84 6.5 0.5 5.16 0.5 3.5C0.5 1.84 1.84 0.5 3.5 0.5C5.16 0.5 6.5 1.84 6.5 3.5ZM9 11.5C9 13.16 7.66 14.5 6 14.5C4.34 14.5 3 13.16 3 11.5C3 9.84 4.34 8.5 6 8.5C7.66 8.5 9 9.84 9 11.5ZM17.5 11.5C17.5 13.16 16.16 14.5 14.5 14.5C12.84 14.5 11.5 13.16 11.5 11.5C11.5 9.84 12.84 8.5 14.5 8.5C16.16 8.5 17.5 9.84 17.5 11.5Z"/>
          </svg>
        </a>

        <nav style={{
          display: 'flex',
          gap: 24,
          alignItems: 'center',
        }}
        className="desktop-nav"
        >
          {siteConfig.nav.links.map((link) => (
            <a
              key={link.label}
              href={link.href}
              style={{
                fontSize: 12,
                fontWeight: 400,
                color: 'var(--text-primary)',
                textDecoration: 'none',
                transition: 'color 0.2s',
                letterSpacing: '-0.01em',
              }}
              onMouseOver={(e) => (e.currentTarget.style.color = 'var(--accent)')}
              onMouseOut={(e) => (e.currentTarget.style.color = 'var(--text-primary)')}
            >
              {link.label}
            </a>
          ))}
        </nav>

        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <button aria-label="Search" style={{ background: 'none', border: 'none', color: 'var(--text-primary)', padding: 4 }}>
            <svg width="15" height="15" viewBox="0 0 15 15" fill="none" stroke="currentColor" strokeWidth="1.8">
              <circle cx="6.5" cy="6.5" r="5" />
              <line x1="10.5" y1="10.5" x2="14" y2="14" />
            </svg>
          </button>
          <button aria-label="Shopping bag" style={{ background: 'none', border: 'none', color: 'var(--text-primary)', padding: 4 }}>
            <svg width="14" height="17" viewBox="0 0 14 17" fill="none" stroke="currentColor" strokeWidth="1.5">
              <path d="M1 5h12v10a1 1 0 01-1 1H2a1 1 0 01-1-1V5z" />
              <path d="M4.5 5V3.5a2.5 2.5 0 015 0V5" />
            </svg>
          </button>
          <button
            aria-label="Menu"
            className="mobile-menu-btn"
            onClick={() => setMenuOpen(!menuOpen)}
            style={{ background: 'none', border: 'none', color: 'var(--text-primary)', padding: 4, display: 'none' }}
          >
            <svg width="18" height="18" viewBox="0 0 18 18" fill="currentColor">
              {menuOpen ? (
                <path d="M3 3l12 12M3 15L15 3" stroke="currentColor" strokeWidth="1.5" fill="none" />
              ) : (
                <>
                  <rect y="3" width="18" height="1.5" rx="0.75" />
                  <rect y="8.25" width="18" height="1.5" rx="0.75" />
                  <rect y="13.5" width="18" height="1.5" rx="0.75" />
                </>
              )}
            </svg>
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="mobile-menu" style={{
          padding: '8px 22px 20px',
          borderTop: '1px solid var(--border)',
        }}>
          {siteConfig.nav.links.map((link) => (
            <a
              key={link.label}
              href={link.href}
              style={{
                display: 'block',
                padding: '10px 0',
                fontSize: 14,
                color: 'var(--text-primary)',
                textDecoration: 'none',
                borderBottom: '1px solid var(--border)',
              }}
              onClick={() => setMenuOpen(false)}
            >
              {link.label}
            </a>
          ))}
        </div>
      )}

      <style>{`
        @media (max-width: 768px) {
          .desktop-nav { display: none !important; }
          .mobile-menu-btn { display: block !important; }
        }
      `}</style>
    </header>
  )
}

