import { useState } from 'react'
import { siteConfig } from '../config/site'

function FooterSection({ title, links }: { title: string; links: string[] }) {
  const [open, setOpen] = useState(false)

  return (
    <div className="footer-section" data-open={open}>
      <h3
        onClick={() => setOpen(!open)}
        style={{
          fontSize: 12,
          fontWeight: 600,
          color: 'var(--text-primary)',
          marginBottom: 8,
          cursor: 'pointer',
          letterSpacing: '-0.01em',
        }}
      >
        {title}
      </h3>
      <div className="footer-links">
        {links.map((link) => (
          <a
            key={link}
            href="#"
            style={{
              display: 'block',
              fontSize: 12,
              color: 'var(--text-secondary)',
              textDecoration: 'none',
              lineHeight: '2',
            }}
          >
            {link}
          </a>
        ))}
      </div>

      <style>{`
        @media (max-width: 768px) {
          .footer-section .footer-links { display: none; }
          .footer-section[data-open="true"] .footer-links { display: block; }
          .footer-section h3::after { content: '+'; float: right; font-size: 14px; font-weight: 400; }
          .footer-section[data-open="true"] h3::after { content: '−'; }
        }
      `}</style>
    </div>
  )
}

export default function Footer() {
  return (
    <footer style={{
      background: 'var(--bg-secondary)',
      borderTop: '1px solid var(--border)',
      padding: '20px 0 10px',
    }}>
      <div style={{
        maxWidth: 980,
        margin: '0 auto',
        padding: '0 22px',
      }}>
        {/* Legal footnotes */}
        <div style={{
          paddingBottom: 16,
          borderBottom: '1px solid var(--border)',
          marginBottom: 16,
        }}>
          {siteConfig.legalFootnotes.map((note, i) => (
            <p key={i} style={{
              fontSize: 12,
              color: 'var(--text-tertiary)',
              lineHeight: 1.5,
              marginBottom: 4,
            }}>
              {note}
            </p>
          ))}
        </div>

        {/* Footer sections grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))',
          gap: 24,
          paddingBottom: 16,
          borderBottom: '1px solid var(--border)',
          marginBottom: 16,
        }}>
          <FooterSection title="Shop and Learn" links={siteConfig.footer.shopAndLearn} />
          <FooterSection title="Orchard Wallet" links={siteConfig.footer.wallet} />
          <FooterSection title="Account" links={siteConfig.footer.account} />
          <FooterSection title="Entertainment" links={siteConfig.footer.entertainment} />
          <FooterSection title="Orchard Store" links={siteConfig.footer.store} />
          <FooterSection title="For Business" links={siteConfig.footer.business} />
          <FooterSection title="For Education" links={siteConfig.footer.education} />
        </div>

        {/* Bottom */}
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: 8,
        }}>
          <p style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>
            Copyright © 2026 Orchard Inc. All rights reserved.
          </p>
          <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
            <a href="#" style={{ fontSize: 12, color: 'var(--text-tertiary)', textDecoration: 'none' }}>Privacy Policy</a>
            <a href="#" style={{ fontSize: 12, color: 'var(--text-tertiary)', textDecoration: 'none' }}>Terms of Use</a>
            <a href="#" style={{ fontSize: 12, color: 'var(--text-tertiary)', textDecoration: 'none' }}>Sales and Refunds</a>
            <a href="#" style={{ fontSize: 12, color: 'var(--text-tertiary)', textDecoration: 'none' }}>Site Map</a>
          </div>
        </div>
      </div>
    </footer>
  )
}

