import { useRef, useState, useEffect, ReactNode } from 'react'

interface CarouselProps {
  children: ReactNode[]
  itemWidth?: number
  gap?: number
}

export default function ProductCarousel({ children, itemWidth = 280, gap = 16 }: CarouselProps) {
  const trackRef = useRef<HTMLDivElement>(null)
  const [canScrollLeft, setCanScrollLeft] = useState(false)
  const [canScrollRight, setCanScrollRight] = useState(true)

  const checkScroll = () => {
    const el = trackRef.current
    if (!el) return
    setCanScrollLeft(el.scrollLeft > 0)
    setCanScrollRight(el.scrollLeft < el.scrollWidth - el.clientWidth - 5)
  }

  useEffect(() => {
    checkScroll()
    const el = trackRef.current
    if (el) el.addEventListener('scroll', checkScroll)
    return () => { if (el) el.removeEventListener('scroll', checkScroll) }
  }, [])

  const scroll = (direction: 'left' | 'right') => {
    const el = trackRef.current
    if (!el) return
    const scrollAmount = itemWidth + gap
    el.scrollBy({ left: direction === 'left' ? -scrollAmount : scrollAmount, behavior: 'smooth' })
  }

  return (
    <div style={{ position: 'relative' }}>
      {canScrollLeft && (
        <button
          onClick={() => scroll('left')}
          aria-label="Previous"
          className="carousel-arrow left"
        >
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="#1d1d1f" strokeWidth="2" strokeLinecap="round">
            <path d="M9 2L4 7l5 5" />
          </svg>
        </button>
      )}

      <div
        ref={trackRef}
        className="carousel-track"
        style={{ gap, padding: '0 48px' }}
      >
        {children}
      </div>

      {canScrollRight && (
        <button
          onClick={() => scroll('right')}
          aria-label="Next"
          className="carousel-arrow right"
        >
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="#1d1d1f" strokeWidth="2" strokeLinecap="round">
            <path d="M5 2l5 5-5 5" />
          </svg>
        </button>
      )}
    </div>
  )
}

export function ProductCard({
  name,
  tagline,
  price,
  monthly,
  badge,
  gradient,
  textColor = '#1d1d1f',
  style: customStyle,
}: {
  name: string
  tagline?: string
  price: string
  monthly?: string
  badge?: string
  gradient: string
  textColor?: string
  style?: React.CSSProperties
}) {
  return (
    <div style={{
      minWidth: 280,
      maxWidth: 280,
      borderRadius: 'var(--radius)',
      background: gradient,
      padding: '28px 24px 24px',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'space-between',
      minHeight: 360,
      flexShrink: 0,
      color: textColor,
      position: 'relative',
      overflow: 'hidden',
      ...customStyle,
    }}>
      {badge && (
        <span style={{
          position: 'absolute',
          top: 16,
          left: 24,
          fontSize: 11,
          fontWeight: 600,
          color: textColor === '#fff' ? 'rgba(255,255,255,0.8)' : 'var(--accent)',
          textTransform: 'uppercase',
          letterSpacing: '0.05em',
        }}>
          {badge}
        </span>
      )}

      <div>
        {/* Product image placeholder */}
        <div style={{
          width: '100%',
          height: 140,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          marginBottom: 16,
          opacity: 0.85,
        }}>
          <div style={{
            width: 80,
            height: 80,
            borderRadius: '50%',
            background: textColor === '#fff' ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.06)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 28,
          }}>
            {name.includes('Phone') ? '📱' : name.includes('Laptop') ? '💻' : name.includes('Tablet') ? '📋' : name.includes('Headphone') ? '🎧' : name.includes('Earbuds') ? '🎵' : name.includes('Smartwatch') ? '⌚' : name.includes('Speaker') ? '🔊' : name.includes('Desktop') ? '🖥️' : name.includes('Tracker') ? '📍' : '📦'}
          </div>
        </div>

        <h3 style={{ fontSize: 20, fontWeight: 600, marginBottom: 4, lineHeight: 1.2, letterSpacing: '-0.01em' }}>
          {name}
        </h3>
        {tagline && (
          <p style={{ fontSize: 14, opacity: 0.8, lineHeight: 1.4, marginBottom: 8 }}>
            {tagline}
          </p>
        )}
      </div>

      <div>
        <p style={{ fontSize: 14, fontWeight: 500, marginBottom: 2 }}>{price}</p>
        {monthly && (
          <p style={{ fontSize: 12, opacity: 0.7 }}>{monthly}</p>
        )}
      </div>
    </div>
  )
}

export function SmallProductCard({
  name,
  price,
  gradient,
  note,
}: {
  name: string
  price: string
  gradient: string
  note?: string
}) {
  return (
    <div style={{
      minWidth: 220,
      maxWidth: 220,
      borderRadius: 'var(--radius)',
      background: gradient,
      padding: '20px 20px 16px',
      display: 'flex',
      flexDirection: 'column',
      minHeight: 260,
      flexShrink: 0,
      color: gradient.includes('1d1d1f') || gradient.includes('0c0c0c') || gradient.includes('2d2d2d') ? '#fff' : '#1d1d1f',
      position: 'relative',
    }}>
      <div style={{
        width: '100%',
        height: 100,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        marginBottom: 12,
      }}>
        <div style={{
          width: 56,
          height: 56,
          borderRadius: '50%',
          background: 'rgba(255,255,255,0.15)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: 22,
        }}>
          {name.includes('Case') ? '🛡️' : name.includes('Strap') ? '🔗' : name.includes('Charger') ? '⚡' : name.includes('Keyboard') ? '⌨️' : name.includes('Battery') ? '🔋' : name.includes('Headphone') ? '🎧' : name.includes('Earbuds') ? '🎵' : name.includes('Speaker') ? '🔊' : name.includes('PowerBuds') ? '🏃' : '📦'}
        </div>
      </div>

      <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 4, lineHeight: 1.3, letterSpacing: '-0.01em' }}>
        {name}
      </h3>
      {note && (
        <p style={{ fontSize: 11, opacity: 0.7, marginBottom: 4 }}>{note}</p>
      )}
      <p style={{ fontSize: 14, fontWeight: 500, marginTop: 'auto' }}>{price}</p>
    </div>
  )
}

export function HelpCard({ title, description, icon }: { title: string; description: string; icon: string }) {
  return (
    <div style={{
      minWidth: 240,
      maxWidth: 240,
      borderRadius: 'var(--radius)',
      background: 'var(--bg-secondary)',
      padding: '24px 20px',
      flexShrink: 0,
    }}>
      <div style={{ fontSize: 32, marginBottom: 12 }}>{icon}</div>
      <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 6, color: 'var(--text-primary)' }}>{title}</h3>
      <p style={{ fontSize: 13, color: 'var(--text-secondary)', lineHeight: 1.4 }}>{description}</p>
    </div>
  )
}

export function InfoCard({ title, description, icon }: { title: string; description: string; icon: string }) {
  return (
    <div style={{
      minWidth: 200,
      maxWidth: 200,
      borderRadius: 'var(--radius)',
      background: 'var(--bg-secondary)',
      padding: '24px 20px',
      flexShrink: 0,
      textAlign: 'center',
    }}>
      <div style={{ fontSize: 28, marginBottom: 10 }}>{icon}</div>
      <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 4, color: 'var(--text-primary)' }}>{title}</h3>
      <p style={{ fontSize: 12, color: 'var(--text-secondary)', lineHeight: 1.4 }}>{description}</p>
    </div>
  )
}

