import { useState } from 'react'
import Header from '../components/Header'
import Footer from '../components/Footer'
import { siteConfig } from '../config/site'

function ProductTile({ name, tagline, gradient, textColor }: { name: string; tagline: string; gradient: string; textColor: string }) {
  return (
    <div style={{
      borderRadius: 'var(--radius)',
      background: gradient,
      padding: '40px 36px 32px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'flex-start',
      minHeight: 420,
      color: textColor,
      position: 'relative',
      overflow: 'hidden',
      cursor: 'pointer',
      transition: 'transform 0.3s ease, box-shadow 0.3s ease',
    }}
    onMouseOver={(e) => { e.currentTarget.style.transform = 'scale(1.01)'; e.currentTarget.style.boxShadow = 'var(--shadow-lg)' }}
    onMouseOut={(e) => { e.currentTarget.style.transform = 'scale(1)'; e.currentTarget.style.boxShadow = 'none' }}
    >
      <div style={{
        width: 120,
        height: 120,
        borderRadius: '50%',
        background: textColor === '#fff' ? 'rgba(255,255,255,0.12)' : 'rgba(0,0,0,0.06)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: 48,
        marginBottom: 20,
      }}>
        {name === 'Phone' ? '📱' : name === 'Laptop Neo' ? '💻' : name === 'Tablet Pro' ? '📋' : name === 'Laptop Pro' ? '💻' : name === 'Earbuds Pro 3' ? '🎵' : '🔄'}
      </div>

      <h2 style={{ fontSize: 36, fontWeight: 700, marginBottom: 6, textAlign: 'center', letterSpacing: '-0.03em', lineHeight: 1.1 }}>
        {name}
      </h2>
      <p style={{ fontSize: 17, opacity: 0.8, textAlign: 'center', marginBottom: 16, maxWidth: 300, lineHeight: 1.4 }}>
        {tagline}
      </p>

      <div style={{ display: 'flex', gap: 16, marginTop: 8 }}>
        <a href="#" style={{
          fontSize: 17,
          color: textColor === '#fff' ? '#2997ff' : 'var(--accent)',
          textDecoration: 'none',
          fontWeight: 400,
        }}>Learn more →</a>
        <a href="#" style={{
          fontSize: 17,
          color: textColor === '#fff' ? '#2997ff' : 'var(--accent)',
          textDecoration: 'none',
          fontWeight: 400,
        }}>Buy →</a>
      </div>
    </div>
  )
}

function EntertainmentSection() {
  const [activeTab, setActiveTab] = useState<'streaming' | 'fitness' | 'gaming' | 'music'>('streaming')
  const tabs = [
    { key: 'streaming' as const, label: 'Streaming' },
    { key: 'fitness' as const, label: 'Fitness' },
    { key: 'gaming' as const, label: 'Gaming' },
    { key: 'music' as const, label: 'Music' },
  ]

  const content = siteConfig.entertainmentTabs[activeTab]
  const tabGradients: Record<string, string[]> = {
    streaming: ['linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)', 'linear-gradient(135deg, #0f3460 0%, #16213e 100%)', 'linear-gradient(135deg, #16213e 0%, #1a1a2e 100%)', 'linear-gradient(135deg, #0f3460 0%, #1a1a2e 100%)', 'linear-gradient(135deg, #1a1a2e 0%, #0f3460 100%)'],
    fitness: ['linear-gradient(135deg, #11998e 0%, #38ef7d 100%)', 'linear-gradient(135deg, #fc4a1a 0%, #f7b733 100%)', 'linear-gradient(135deg, #8360c3 0%, #2ebf91 100%)', 'linear-gradient(135deg, #ee0979 0%, #ff6a00 100%)', 'linear-gradient(135deg, #2193b0 0%, #6dd5ed 100%)'],
    gaming: ['linear-gradient(135deg, #0c0c0c 0%, #1d1d1f 100%)', 'linear-gradient(135deg, #2d2d2d 0%, #4a4a4a 100%)', 'linear-gradient(135deg, #1d1d1f 0%, #3d3d3f 100%)', 'linear-gradient(135deg, #3d3d3f 0%, #5a5a5c 100%)', 'linear-gradient(135deg, #0c0c0c 0%, #2d2d2d 100%)'],
    music: ['linear-gradient(135deg, #fc466b 0%, #3f5efb 100%)', 'linear-gradient(135deg, #a8edea 0%, #fed6e3 100%)', 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)', 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)'],
  }

  return (
    <section style={{ padding: '60px 0', background: 'var(--bg-primary)' }}>
      <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
        <h2 style={{ fontSize: 40, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 4, color: 'var(--text-primary)' }}>
          Endless entertainment.
        </h2>
        <p style={{ fontSize: 21, color: 'var(--text-secondary)', marginBottom: 28 }}>
          The best experiences. All in one place.
        </p>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: 0, marginBottom: 28, borderBottom: '1px solid var(--border)' }}>
          {tabs.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              style={{
                padding: '10px 20px',
                fontSize: 14,
                fontWeight: activeTab === tab.key ? 600 : 400,
                color: activeTab === tab.key ? 'var(--text-primary)' : 'var(--text-secondary)',
                background: 'none',
                border: 'none',
                borderBottom: activeTab === tab.key ? '2px solid var(--text-primary)' : '2px solid transparent',
                cursor: 'pointer',
                transition: 'all 0.2s',
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Content cards */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
          gap: 16,
        }}>
          {content.map((item, i) => (
            <div
              key={`${activeTab}-${i}`}
              style={{
                borderRadius: 'var(--radius-sm)',
                background: tabGradients[activeTab][i % tabGradients[activeTab].length],
                padding: '20px 16px',
                minHeight: 200,
                color: activeTab === 'music' && (i === 1 || i === 4) ? '#1d1d1f' : activeTab === 'fitness' ? '#1d1d1f' : '#fff',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'flex-end',
                transition: 'transform 0.2s',
                cursor: 'pointer',
              }}
              onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.03)'}
              onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
            >
              <h4 style={{ fontSize: 16, fontWeight: 600, marginBottom: 4, lineHeight: 1.2 }}>{item.title}</h4>
              <p style={{ fontSize: 12, opacity: 0.8, marginBottom: 8, lineHeight: 1.3 }}>{item.subtitle}</p>
              <a href="#" style={{
                fontSize: 13,
                color: activeTab === 'music' && (i === 1 || i === 4) ? 'var(--accent)' : activeTab === 'fitness' ? 'var(--accent)' : '#2997ff',
                textDecoration: 'none',
                fontWeight: 500,
              }}>{item.cta} →</a>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

export default function HomePage() {
  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />

      {/* Ribbon Banner */}
      <div style={{
        background: 'var(--bg-secondary)',
        padding: '10px 22px',
        textAlign: 'center',
        borderBottom: '1px solid var(--border)',
      }}>
        <p style={{ fontSize: 14, color: 'var(--text-primary)' }}>
          <a href="#" style={{ color: 'var(--accent)', textDecoration: 'none' }}>
            {siteConfig.ribbonBanner}
          </a>
        </p>
      </div>

      {/* Hero Section */}
      <section style={{
        padding: '80px 22px 40px',
        textAlign: 'center',
        background: 'var(--bg-primary)',
      }}>
        <h1 style={{ fontSize: 56, fontWeight: 700, letterSpacing: '-0.04em', marginBottom: 8, lineHeight: 1.05, color: 'var(--text-primary)' }}>
          Store
        </h1>
        <p style={{ fontSize: 21, color: 'var(--text-secondary)', marginBottom: 20, maxWidth: 600, margin: '0 auto', lineHeight: 1.4 }}>
          The best way to buy the products you love.
        </p>
        <div style={{ display: 'flex', justifyContent: 'center', gap: 24, flexWrap: 'wrap' }}>
          <a href="#" style={{ fontSize: 17, color: 'var(--accent)', textDecoration: 'none' }}>Connect with a Specialist →</a>
          <a href="#" style={{ fontSize: 17, color: 'var(--accent)', textDecoration: 'none' }}>Find an Orchard Store →</a>
          <a href="#" style={{ fontSize: 17, color: 'var(--accent)', textDecoration: 'none' }}>Visit an Orchard Store →</a>
        </div>
      </section>

      {/* Product Grid */}
      <section style={{
        padding: '0 22px 60px',
        maxWidth: 1060,
        margin: '0 auto',
      }}>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: 16,
        }}
        className="product-grid"
        >
          {siteConfig.homepageProducts.map((product) => (
            <ProductTile
              key={product.name}
              name={product.name}
              tagline={product.tagline}
              gradient={product.gradient}
              textColor={product.textColor}
            />
          ))}
        </div>
      </section>

      {/* Entertainment */}
      <EntertainmentSection />

      <Footer />

      <style>{`
        @media (max-width: 768px) {
          .product-grid {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>
    </div>
  )
}

