import Header from '../components/Header'
import Footer from '../components/Footer'
import ProductCarousel, { ProductCard, SmallProductCard, HelpCard, InfoCard } from '../components/ProductCarousel'
import { siteConfig } from '../config/site'

function SectionHeading({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 48px', marginBottom: 20 }}>
      <h2 style={{ fontSize: 36, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 4, color: 'var(--text-primary)' }}>
        {title}
      </h2>
      {subtitle && (
        <p style={{ fontSize: 17, color: 'var(--text-secondary)', lineHeight: 1.4 }}>
          {subtitle}
        </p>
      )}
    </div>
  )
}

export default function StorePage() {
  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />

      {/* Store Hero */}
      <section style={{
        padding: '60px 22px 32px',
        textAlign: 'center',
        background: 'var(--bg-primary)',
      }}>
        <h1 style={{ fontSize: 52, fontWeight: 700, letterSpacing: '-0.04em', marginBottom: 6, lineHeight: 1.05, color: 'var(--text-primary)' }}>
          Store
        </h1>
        <p style={{ fontSize: 21, color: 'var(--text-secondary)', maxWidth: 500, margin: '0 auto', lineHeight: 1.4 }}>
          The best way to buy the products you love.
        </p>
        <div style={{ display: 'flex', justifyContent: 'center', gap: 20, marginTop: 16, flexWrap: 'wrap' }}>
          <a href="#" style={{ fontSize: 17, color: 'var(--accent)', textDecoration: 'none' }}>Connect with a Specialist →</a>
          <a href="#" style={{ fontSize: 17, color: 'var(--accent)', textDecoration: 'none' }}>Find an Orchard Store →</a>
          <a href="#" style={{ fontSize: 17, color: 'var(--accent)', textDecoration: 'none' }}>Visit an Orchard Store →</a>
        </div>
      </section>

      {/* Product Icon Bar */}
      <section style={{
        padding: '16px 0',
        borderTop: '1px solid var(--border)',
        borderBottom: '1px solid var(--border)',
        background: 'var(--bg-primary)',
      }}>
        <div style={{
          maxWidth: 980,
          margin: '0 auto',
          padding: '0 22px',
          display: 'flex',
          justifyContent: 'center',
          gap: 32,
          flexWrap: 'wrap',
          overflowX: 'auto',
        }}>
          {siteConfig.productCategories.map((cat) => (
            <a
              key={cat.name}
              href={cat.href}
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                textDecoration: 'none',
                gap: 6,
                minWidth: 64,
                flexShrink: 0,
              }}
            >
              <span style={{ fontSize: 28 }}>{cat.emoji}</span>
              <span style={{ fontSize: 11, color: 'var(--text-secondary)', fontWeight: 400, whiteSpace: 'nowrap' }}>{cat.name}</span>
            </a>
          ))}
        </div>
      </section>

      {/* Latest Products */}
      <section style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <SectionHeading title="The latest." subtitle="Take a look at what's new, right now." />
        <ProductCarousel itemWidth={280} gap={16}>
          {siteConfig.latestProducts.map((product) => (
            <ProductCard
              key={product.name}
              name={product.name}
              tagline={product.tagline}
              price={product.price}
              monthly={product.monthly}
              badge={product.badge}
              gradient={product.gradient}
              textColor={product.textColor}
            />
          ))}
        </ProductCarousel>
      </section>

      {/* Help Section */}
      <section style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <SectionHeading title="Help is here." subtitle="Whenever and however you need it." />
        <ProductCarousel itemWidth={240} gap={16}>
          {siteConfig.helpItems.map((item) => (
            <HelpCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Store Difference */}
      <section style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <SectionHeading title="The Orchard Store difference." subtitle="Even more reasons to shop with us." />
        <ProductCarousel itemWidth={200} gap={16}>
          {siteConfig.storeDifference.map((item) => (
            <InfoCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Accessories */}
      <section style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <SectionHeading title="Accessories." subtitle="Essentials that pair perfectly with your favorite devices." />
        <ProductCarousel itemWidth={220} gap={16}>
          {siteConfig.accessories.map((item) => (
            <SmallProductCard
              key={item.name}
              name={item.name}
              price={item.price}
              gradient={item.gradient}
            />
          ))}
        </ProductCarousel>
      </section>

      {/* Audio */}
      <section style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <SectionHeading title="Loud and clear." subtitle="Unparalleled choices for rich, high-quality sound." />
        {siteConfig.audioPromo && (
          <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 48px', marginBottom: 16 }}>
            <p style={{ fontSize: 14, color: 'var(--accent)', fontWeight: 500 }}>{siteConfig.audioPromo}</p>
          </div>
        )}
        <ProductCarousel itemWidth={220} gap={16}>
          {siteConfig.audioProducts.map((item) => (
            <SmallProductCard
              key={item.name}
              name={item.name}
              price={item.price}
              gradient={item.gradient}
              note={item.note}
            />
          ))}
        </ProductCarousel>
      </section>

      {/* Brand Collaboration */}
      <section style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <div style={{
            borderRadius: 'var(--radius)',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            padding: '48px 40px',
            color: '#fff',
            textAlign: 'center',
          }}>
            <h2 style={{ fontSize: 32, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 8, color: '#fff' }}>
              {siteConfig.brandCollab.title}
            </h2>
            <p style={{ fontSize: 17, opacity: 0.9, marginBottom: 12, maxWidth: 500, margin: '0 auto 12px', lineHeight: 1.4 }}>
              {siteConfig.brandCollab.subtitle}
            </p>
            <p style={{ fontSize: 14, opacity: 0.8, maxWidth: 440, margin: '0 auto 16px', lineHeight: 1.4 }}>
              {siteConfig.brandCollab.description}
            </p>
            <a href="#" style={{ fontSize: 17, color: '#2997ff', textDecoration: 'none' }}>Shop the collection →</a>
          </div>
        </div>
      </section>

      {/* Experience / Savings */}
      <section style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <SectionHeading title="Savings and offers." subtitle="Exclusive deals, special stores and more." />
        <ProductCarousel itemWidth={200} gap={16}>
          {siteConfig.savingsOffers.map((item) => (
            <InfoCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Quick Links */}
      <section style={{ padding: '32px 0 48px', background: 'var(--bg-secondary)', borderTop: '1px solid var(--border)' }}>
        <div style={{
          maxWidth: 980,
          margin: '0 auto',
          padding: '0 22px',
          display: 'flex',
          justifyContent: 'center',
          gap: 24,
          flexWrap: 'wrap',
        }}>
          {siteConfig.quickLinks.map((link) => (
            <a
              key={link.label}
              href={link.href}
              style={{
                padding: '10px 20px',
                borderRadius: 20,
                background: 'var(--bg-primary)',
                border: '1px solid var(--border)',
                fontSize: 14,
                color: 'var(--text-primary)',
                textDecoration: 'none',
                transition: 'box-shadow 0.2s',
              }}
              onMouseOver={(e) => e.currentTarget.style.boxShadow = 'var(--shadow)'}
              onMouseOut={(e) => e.currentTarget.style.boxShadow = 'none'}
            >
              {link.label}
            </a>
          ))}
        </div>
      </section>

      <Footer />
    </div>
  )
}

