raw_arguments.content:
import { useState, useEffect } from 'react'
import Header from '../components/Header'
import Footer from '../components/Footer'
import ProductCarousel, { ProductCard, SmallProductCard, HelpCard, InfoCard } from '../components/ProductCarousel'
import { siteConfig } from '../config/site'

const sections = [
  { id: 'all-models', label: 'All Models' },
  { id: 'shopping-guides', label: 'Shopping Guides' },
  { id: 'ways-to-save', label: 'Ways to Save' },
  { id: 'store-difference', label: 'Store Difference' },
  { id: 'accessories', label: 'Accessories' },
  { id: 'setup-support', label: 'Setup & Support' },
  { id: 'product-experience', label: 'Product Experience' },
  { id: 'special-stores', label: 'Special Stores' },
]

function SectionHeading({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <h2 style={{ fontSize: 36, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 4, color: 'var(--text-primary)' }}>
        {title}
      </h2>
      {subtitle && (
        <p style={{ fontSize: 17, color: 'var(--text-secondary)', lineHeight: 1.4 }}>{subtitle}</p>
      )}
    </div>
  )
}

function StickyNav({ activeId }: { activeId: string }) {
  return (
    <nav className="sticky-nav">
      <div style={{
        maxWidth: 980,
        margin: '0 auto',
        padding: '0 22px',
        display: 'flex',
        gap: 0,
        overflowX: 'auto',
        scrollbarWidth: 'none',
      }}>
        {sections.map((s) => (
          <a
            key={s.id}
            href={`#${s.id}`}
            className={activeId === s.id ? 'active' : ''}
            style={{
              padding: '10px 16px',
              fontSize: 12,
              fontWeight: activeId === s.id ? 600 : 400,
              color: activeId === s.id ? 'var(--text-primary)' : 'var(--text-secondary)',
              whiteSpace: 'nowrap',
              borderBottom: activeId === s.id ? '2px solid var(--text-primary)' : '2px solid transparent',
              transition: 'all 0.2s',
            }}
          >
            {s.label}
          </a>
        ))}
      </div>
    </nav>
  )
}

export default function ShopTabletsPage() {
  const [activeId, setActiveId] = useState('all-models')

  useEffect(() => {
    const handleScroll = () => {
      for (const s of sections) {
        const el = document.getElementById(s.id)
        if (el) {
          const rect = el.getBoundingClientRect()
          if (rect.top <= 120 && rect.bottom > 120) {
            setActiveId(s.id)
            break
          }
        }
      }
    }
    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <StickyNav activeId={activeId} />

      {/* Category Hero */}
      <section style={{
        padding: '60px 22px 32px',
        textAlign: 'center',
        background: 'linear-gradient(180deg, #f5f5f7 0%, #ffffff 100%)',
      }}>
        <h1 style={{ fontSize: 52, fontWeight: 700, letterSpacing: '-0.04em', marginBottom: 6, lineHeight: 1.05, color: 'var(--text-primary)' }}>
          Shop Tablets
        </h1>
        <p style={{ fontSize: 21, color: 'var(--text-secondary)', maxWidth: 500, margin: '0 auto', lineHeight: 1.4 }}>
          Find the perfect Tablet for you.
        </p>
      </section>

      {/* All Models */}
      <section id="all-models" style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="All models. Take your pick." />
        </div>
        <ProductCarousel itemWidth={280} gap={16}>
          {siteConfig.tabletModels.map((product) => (
            <ProductCard
              key={product.name}
              name={product.name}
              price={product.price}
              monthly={product.monthly}
              badge={product.badge}
              gradient={product.gradient}
              textColor={product.textColor}
            />
          ))}
        </ProductCarousel>
      </section>

      {/* Shopping Guides */}
      <section id="shopping-guides" style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="Shopping guides. Can't decide? Start here." />
        </div>
        <ProductCarousel itemWidth={240} gap={16}>
          {siteConfig.shoppingGuides.map((item) => (
            <HelpCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Ways to Save */}
      <section id="ways-to-save" style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="Ways to save. Find what works for you." />
        </div>
        <ProductCarousel itemWidth={200} gap={16}>
          {siteConfig.waysToSave.map((item) => (
            <InfoCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Store Difference */}
      <section id="store-difference" style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="The Orchard Store difference." subtitle="Even more reasons to shop with us." />
        </div>
        <ProductCarousel itemWidth={200} gap={16}>
          {siteConfig.storeDifference.map((item) => (
            <InfoCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Accessories */}
      <section id="accessories" style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="Accessories." subtitle="Essentials that pair perfectly with your Tablet." />
        </div>
        <ProductCarousel itemWidth={220} gap={16}>
          {siteConfig.accessories.map((item) => (
            <SmallProductCard
              key={item.name}
              name={item.name}
              price={item.price}
              gradient={item.gradient}
            />
          ))}
        </ProductCarousel>
      </section>

      {/* Setup & Support */}
      <section id="setup-support" style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="Help is here." subtitle="Whenever and however you need it." />
        </div>
        <ProductCarousel itemWidth={240} gap={16}>
          {siteConfig.helpItems.map((item) => (
            <HelpCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      {/* Product Experience */}
      <section id="product-experience" style={{ padding: '48px 0', background: 'var(--bg-primary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <div style={{
            borderRadius: 'var(--radius)',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            padding: '48px 40px',
            color: '#fff',
            textAlign: 'center',
          }}>
            <h2 style={{ fontSize: 28, fontWeight: 700, letterSpacing: '-0.02em', marginBottom: 8, color: '#fff' }}>
              Orchard Intelligence
            </h2>
            <p style={{ fontSize: 17, opacity: 0.85, maxWidth: 460, margin: '0 auto 16px', lineHeight: 1.4 }}>
              Create, communicate, and get things done effortlessly with O4.
            </p>
            <a href="#" style={{ fontSize: 17, color: '#2997ff', textDecoration: 'none' }}>Learn more →</a>
          </div>
        </div>
      </section>

      {/* Special Stores */}
      <section id="special-stores" style={{ padding: '48px 0', background: 'var(--bg-secondary)' }}>
        <div style={{ maxWidth: 980, margin: '0 auto', padding: '0 22px' }}>
          <SectionHeading title="Savings and offers." subtitle="Exclusive deals, special stores and more." />
        </div>
        <ProductCarousel itemWidth={200} gap={16}>
          {siteConfig.savingsOffers.map((item) => (
            <InfoCard key={item.title} title={item.title} description={item.description} icon={item.icon} />
          ))}
        </ProductCarousel>
      </section>

      <Footer />
    </div>
  )
}

