@import "tailwindcss";

:root {
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f7;
  --bg-tertiary: #fbfbfd;
  --text-primary: #1d1d1f;
  --text-secondary: #6e6e73;
  --text-tertiary: #86868b;
  --accent: #0066cc;
  --accent-hover: #004999;
  --border: #d2d2d7;
  --surface: #ffffff;
  --shadow: 0 2px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 4px 24px rgba(0,0,0,0.12);
  --radius: 18px;
  --radius-sm: 12px;
  --font-display: "SF Pro Display", "Helvetica Neue", "Inter", system-ui, -apple-system, sans-serif;
  --font-body: "SF Pro Text", "Helvetica Neue", "Inter", system-ui, -apple-system, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--text-primary);
  background: var(--bg-primary);
  line-height: 1.47059;
  font-size: 17px;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.07143;
  letter-spacing: -0.02em;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

button {
  cursor: pointer;
  font-family: inherit;
}

::selection {
  background: rgba(0, 102, 204, 0.15);
}

/* Carousel styles */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 0 48px;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow);
  transition: all 0.2s;
}

.carousel-arrow:hover {
  background: #fff;
  box-shadow: var(--shadow-lg);
}

.carousel-arrow.left { left: 12px; }
.carousel-arrow.right { right: 12px; }

/* Sticky nav */
.sticky-nav {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border);
}

.sticky-nav a {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 16px;
  white-space: nowrap;
  transition: color 0.2s;
  text-decoration: none;
}

.sticky-nav a:hover,
.sticky-nav a.active {
  color: var(--text-primary);
  text-decoration: none;
}

